using GameTranslator.Core;
namespace GameTranslator.Core.Tests;
public class ReadingAreaTests_058
{
    [Fact]public void PartialOcrKeepsTheFullMessageAndPageDimensions(){var tracker=new PhonePanelTracker();var full=new PanelCell("Sorry, something came up. I'll see you later.","",new(.1,.2,.9,.4),"#FFFFFF","#20232A",.03,true);tracker.Observe(new(400,700,"phone",null,[full]),0);var partial=tracker.Observe(new(360,650,"phone",null,[full with{Source="Sorry, something came up.",LineHeight=.04}]),500)!;Assert.Equal(full.Source,Assert.Single(partial.Cells).Source);Assert.Equal(400,partial.Width);Assert.Equal(700,partial.Height);}
    [Fact]public void NewPageConfirmationDoesNotRequireEveryOcrLineToRepeatExactly(){var t=new PhonePanelTracker();PanelCell C(string text,double y)=>new(text,"",new(.1,y,.9,y+.08),"#FFFFFF","#20232A",.03,true);t.Observe(new(400,700,"phone",null,[C("Original conversation.",.2)]),0);t.Observe(new(400,700,"phone",null,[C("This is a completely new page.",.2),C("One line still fading.",.5)]),500);var confirmed=t.Observe(new(400,700,"phone",null,[C("This is a completely new page.",.2)]),1000)!;Assert.Contains(confirmed.Cells,c=>c.Source=="This is a completely new page.");Assert.DoesNotContain(confirmed.Cells,c=>c.Source=="Original conversation.");}
    [Fact]public async Task NotificationOwnsItsTextInsteadOfBecomingDialogue(){long now=0;var notice=ReadingArea.Notification() with{AutoDetect=false,Source=new(.6,.95,.65,.95)};using var s=new ReadingAreaSession([notice],()=>new NoticeReader(),new FakeTranslator(),()=>now);await s.ProcessAsync(Frame.Blank(400,300));var message=new TextLine("There is a pecking order around here.",new(.67,.7,.94,.9));Assert.Empty(s.WithoutMessageText(new([message]),new(0,0,1,1)).Lines);Assert.Single(s.WithoutMessageText(new([message with{Box=new(.1,.7,.4,.9)}]),new(0,0,1,1)).Lines);}
    private sealed class NoticeReader:ITextReader{public string Read(Frame f)=>"";public Reading ReadSpatial(Frame f)=>new([new("Wade",new(.2,.02,.8,.08)),new("There is a pecking order around here.",new(.1,.2,.9,.8))]);}
    [Theory][InlineData("هذول يبغى","هؤلاء يريد")][InlineData("وش تبغى؟","ماذا تريد؟")][InlineData("اللي قاله عشان ما يروح.","اللي قاله عشان ما يروح.")]
    public void SafeFormalFormsDoNotGuessAnAmbiguousConnector(string value,string expected)=>Assert.Equal(expected,ArabicRegister.Normalize(value));
    [Fact]public void ShortNotificationDoesNotRequireAConversationBody(){var tracker=new PhonePanelTracker();var panel=new PanelLayout(300,90,"notification",null,[new("Saved","",new(.1,.2,.9,.8),"#FFFFFF","#20232A",.2,Heading:true)]);Assert.NotNull(tracker.Observe(panel,0));Assert.NotNull(tracker.Observe(panel,500));}
    [Fact]public void HeaderOcrTypoCannotReplaceAConfirmedConversation(){var t=new PhonePanelTracker();PanelCell H(string text)=>new(text,"",new(.3,.02,.7,.07),"#FFFFFF","#20232A",.03,Heading:true);var b=new PanelCell("Sorry, something came up.","",new(.1,.3,.9,.4),"#FFFFFF","#20232A",.03,true);t.Observe(new(400,700,"phone",null,[H("Lucia"),b]),0);var observed=t.Observe(new(400,700,"phone",null,[H("Lucla"),b]),900)!;Assert.Equal("Lucia",observed.Cells.First(c=>c.Heading).Source);}
    [Fact]public void ANewNotificationFromTheSameSenderIsNotTheOldPage(){var t=new PhonePanelTracker();var header=new PanelCell("Wade","",new(.2,.01,.8,.08),"#FFFFFF","#20232A",.03,Heading:true);PanelCell C(string text)=>new(text,"",new(.1,.2,.9,.9),"#FFFFFF","#20232A",.03,true);t.Observe(new(400,150,"notification",null,[header,C("Meet me at home.")]),0);var next=new PanelLayout(400,240,"notification",null,[header,C("A different message has arrived.")]);t.Observe(next,500);Assert.Equal(240,t.Observe(next,1000)!.Height);}
    [Fact]public void NarrowPhoneControlReservesEnoughLinesBeforeItsTranslationArrives(){var cell=new PanelCell("Check In","",new(.8,.8,.96,.87),"#2266DD","#FFFFFF",.035,true);var original=SpatialText.ReflowPhone(new(400,700,"phone",null,[cell]),22);var translated=SpatialText.ReflowPhone(new(400,700,"phone",null,[cell with{Text="تسجيل الحضور"}]),22);Assert.Equal(original.Height,translated.Height);Assert.Equal(original.Cells[0].Box,translated.Cells[0].Box);}
    [Fact]public async Task OverlappingNotificationCardsCannotShowTheSameMessageTwice(){long now=0;var first=ReadingArea.Notification() with{AutoDetect=false,Source=new(.6,.95,.65,.95)};var second=first with{Id="duplicate",Output=new(.2,.5,.2,.5)};using var session=new ReadingAreaSession([first,second],()=>new NoticeReader(),new FakeTranslator(),()=>now);var shown=new List<string>();session.Caption+=c=>{if(!c.Clear)lock(shown)shown.Add(c.Id);};await session.ProcessAsync(Frame.Blank(400,300));await session.ProcessAsync(Frame.Blank(400,300));now=500;await session.ProcessAsync(Frame.Blank(400,300));await session.ProcessAsync(Frame.Blank(400,300));for(int i=0;i<30;i++){lock(shown)if(shown.Count>0)break;await Task.Delay(10);}lock(shown){Assert.NotEmpty(shown);Assert.DoesNotContain("duplicate",shown);Assert.All(shown,id=>Assert.Equal(first.Id,id));}}
    [Fact]public async Task UnknownContactNameCannotBlockTheTranslatedNotificationBody(){long now=0;var area=ReadingArea.Notification() with{AutoDetect=false,Source=new(.6,.95,.65,.95)};using var session=new ReadingAreaSession([area],()=>new NoticeReader(),new HeaderFailure(),()=>now);var shown=new TaskCompletionSource<AreaCaption>(TaskCreationOptions.RunContinuationsAsynchronously);session.Caption+=c=>{if(!c.Clear)shown.TrySetResult(c);};await session.ProcessAsync(Frame.Blank(400,300));now=500;await session.ProcessAsync(Frame.Blank(400,300));var caption=await shown.Task.WaitAsync(TimeSpan.FromSeconds(3));Assert.Contains("ترجمة",caption.Text);Assert.Contains(caption.Panel!.Cells,c=>!c.Heading&&c.Text=="ترجمة الرسالة كاملة.");}
    private sealed class HeaderFailure:ITextTranslator{public Task<string> TranslateAsync(string text,CancellationToken token=default)=>Task.FromResult(text=="Wade"?"":"ترجمة الرسالة كاملة.");}
}
